// Returns true when the function is known to need a licence. An unknown
// function returns false, matching renet's runtime behaviour, but a function
// missing here is a bug: renet's completeness gate fails the build for any
// registered function without a tier.
export function requiresLicense(functionName: string): boolean {
  const entry = LICENSE_TIERS[functionName];
  return entry !== undefined && entry.tier !== 'none';
}

// True when renet has no decision for this function yet. Callers that care
// about correctness (rather than just current behaviour) should treat this
// as 'unknown' rather than 'free'.
export function isPendingLicenseDecision(functionName: string): boolean {
  return LICENSE_TIERS[functionName]?.pending === true;
}
